<?php
/**
 * Unified Legacy React & JSON Bundle Importer for Santa Towing Business Manager.
 *
 * Accepts:
 *  - `santa-legacy-browser-export-v1` (generated by legacy-browser-export-snippet.js)
 *  - `santa_towing_billing_v1` (Business Manager / React billing backup)
 *  - `{ content, inventory }` or `{ siteContent, inventory }` site content backups
 *  - `stwc-defaults-v1` (`migration/business-manager-defaults.json`)
 *
 * Tracks and reports: successful, failed, skipped_duplicates, missing_images, broken_relationships.
 *
 * @package Santa_Towing_Business_Manager
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

class STBM_Legacy_Importer {

	/**
	 * Detect schema identifier from uploaded bundle array.
	 *
	 * @param array $bundle Decoded JSON payload.
	 * @return string
	 */
	public static function detect_schema( $bundle ) {
		if ( ! is_array( $bundle ) ) {
			return 'invalid';
		}
		if ( isset( $bundle['schema'] ) && 'santa-legacy-browser-export-v1' === $bundle['schema'] ) {
			return 'santa-legacy-browser-export-v1';
		}
		if ( isset( $bundle['schema'] ) && 'stwc-defaults-v1' === $bundle['schema'] ) {
			return 'stwc-defaults-v1';
		}
		if ( isset( $bundle['backupType'] ) && 'santa_towing_billing_v1' === $bundle['backupType'] ) {
			return 'santa_towing_billing_v1';
		}
		if ( isset( $bundle['content'] ) || isset( $bundle['siteContent'] ) ) {
			return 'santa-content-backup-v1';
		}
		if ( isset( $bundle['customers'] ) || isset( $bundle['invoices'] ) || isset( $bundle['receipts'] ) ) {
			return 'santa_towing_billing_v1';
		}
		return 'unknown';
	}

	/**
	 * Check whether an image reference points to an unresolvable blob URL or missing asset file.
	 *
	 * @param string $url Raw image string.
	 * @return bool True if missing/unresolvable.
	 */
	private static function is_missing_image_ref( $url ) {
		$val = trim( (string) $url );
		if ( '' === $val ) {
			return false;
		}
		if ( 0 === strpos( $val, 'blob:' ) ) {
			return true;
		}
		if ( 0 === strpos( $val, 'data:image/' ) || 0 === strpos( $val, 'http://' ) || 0 === strpos( $val, 'https://' ) ) {
			return false;
		}
		$base = basename( wp_parse_url( $val, PHP_URL_PATH ) ?: $val );
		if ( '' === $base ) {
			return false;
		}
		$theme_path  = trailingslashit( get_template_directory() ) . 'assets/images/' . $base;
		$plugin_path = STBM_PLUGIN_DIR . 'assets/images/' . $base;
		if ( file_exists( $plugin_path ) || file_exists( $theme_path ) ) {
			return false;
		}
		// Check Media Library by filename.
		global $wpdb;
		$like  = '%/' . $wpdb->esc_like( $base );
		$found = (int) $wpdb->get_var(
			$wpdb->prepare(
				"SELECT ID FROM {$wpdb->posts} p INNER JOIN {$wpdb->postmeta} pm ON p.ID = pm.post_id WHERE p.post_type='attachment' AND pm.meta_key IN ('_st_source_filename','_wp_attached_file') AND (pm.meta_value=%s OR pm.meta_value LIKE %s) LIMIT 1",
				$base,
				$like
			)
		);
		return 0 === $found;
	}

	/**
	 * Sanitize nested arbitrary content values recursively.
	 *
	 * @param mixed $val Raw value.
	 * @return mixed
	 */
	private static function sanitize_value( $val ) {
		if ( is_bool( $val ) || is_int( $val ) || is_float( $val ) || null === $val ) {
			return $val;
		}
		if ( is_string( $val ) ) {
			if ( false !== strpos( $val, "\n" ) ) {
				return sanitize_textarea_field( $val );
			}
			return wp_kses_post( $val );
		}
		if ( is_array( $val ) ) {
			$out = array();
			foreach ( $val as $k => $v ) {
				$clean_k         = is_int( $k ) ? $k : sanitize_text_field( (string) $k );
				$out[ $clean_k ] = self::sanitize_value( $v );
			}
			return $out;
		}
		return '';
	}

	/**
	 * Import a supported bundle safely with full validation and migration audit reporting.
	 *
	 * @param array $bundle Decoded JSON payload.
	 * @param array $opts   Options: mode ('merge'|'replace'), dry_run (bool), enforce_caps (bool).
	 * @return array
	 */
	public static function import_bundle( $bundle, $opts = array() ) {
		global $wpdb;

		$mode         = ( isset( $opts['mode'] ) && 'replace' === $opts['mode'] ) ? 'replace' : 'merge';
		$dry_run      = ! empty( $opts['dry_run'] );
		$enforce_caps = ! isset( $opts['enforce_caps'] ) || (bool) $opts['enforce_caps'];
		$schema       = self::detect_schema( $bundle );

		$report = array(
			'ok'                   => false,
			'schema'               => $schema,
			'mode'                 => $mode,
			'dry_run'              => $dry_run,
			'counts'               => array(
				'contentKeys'  => 0,
				'inventory'    => 0,
				'docSettings'  => 0,
				'customers'    => 0,
				'invoices'     => 0,
				'receipts'     => 0,
				'activityLogs' => 0,
				'studioImages' => 0,
			),
			'successful'           => array(),
			'failed'               => array(),
			'skipped_duplicates'   => array(),
			'missing_images'       => array(),
			'broken_relationships' => array(),
		);

		if ( in_array( $schema, array( 'invalid', 'unknown' ), true ) ) {
			$report['failed'][] = 'Unrecognized JSON schema. Expected santa-legacy-browser-export-v1, santa_towing_billing_v1, content backup, or stwc-defaults-v1.';
			return $report;
		}

		// Normalize into canonical sections.
		$content_updates     = array();
		$inventory_sections  = array();
		$doc_settings        = null;
		$customers           = array();
		$invoices            = array();
		$receipts            = array();
		$activity_logs       = array();
		$studio_images       = array();

		if ( 'santa-legacy-browser-export-v1' === $schema ) {
			$d                  = is_array( $bundle['data'] ?? null ) ? $bundle['data'] : array();
			$content_updates    = is_array( $d['siteContentOverrides'] ?? null ) ? $d['siteContentOverrides'] : array();
			$inventory_sections = is_array( $d['inventoryOverrides'] ?? null ) ? $d['inventoryOverrides'] : array();
			$b                  = is_array( $d['billing'] ?? null ) ? $d['billing'] : array();
			$doc_settings       = is_array( $b['settings'] ?? null ) ? $b['settings'] : null;
			$customers          = is_array( $b['customers'] ?? null ) ? $b['customers'] : array();
			$invoices           = is_array( $b['invoices'] ?? null ) ? $b['invoices'] : array();
			$receipts           = is_array( $b['receipts'] ?? null ) ? $b['receipts'] : array();
			$activity_logs      = is_array( $b['activityLogs'] ?? null ) ? $b['activityLogs'] : array();
			$studio_images      = is_array( $d['studioImages'] ?? null ) ? $d['studioImages'] : array();
		} elseif ( 'santa_towing_billing_v1' === $schema ) {
			$doc_settings  = is_array( $bundle['settings'] ?? null ) ? $bundle['settings'] : null;
			$customers     = is_array( $bundle['customers'] ?? null ) ? $bundle['customers'] : array();
			$invoices      = is_array( $bundle['invoices'] ?? null ) ? $bundle['invoices'] : array();
			$receipts      = is_array( $bundle['receipts'] ?? null ) ? $bundle['receipts'] : array();
			$activity_logs = is_array( $bundle['logs'] ?? null ) ? $bundle['logs'] : array();
		} elseif ( 'santa-content-backup-v1' === $schema ) {
			$raw_content = is_array( $bundle['content'] ?? null ) ? $bundle['content'] : ( is_array( $bundle['siteContent'] ?? null ) ? $bundle['siteContent'] : array() );
			if ( ! empty( $raw_content ) ) {
				$content_updates = array( '__nested__' => $raw_content );
			}
			$inventory_sections = is_array( $bundle['inventory'] ?? null ) ? $bundle['inventory'] : array();
		} elseif ( 'stwc-defaults-v1' === $schema ) {
			$doc_settings  = is_array( $bundle['doc_settings'] ?? null ) ? $bundle['doc_settings'] : null;
			$customers     = is_array( $bundle['customers'] ?? null ) ? $bundle['customers'] : array();
			$invoices      = is_array( $bundle['invoices'] ?? null ) ? $bundle['invoices'] : array();
			$receipts      = is_array( $bundle['receipts'] ?? null ) ? $bundle['receipts'] : array();
			$activity_logs = is_array( $bundle['activity_logs'] ?? null ) ? $bundle['activity_logs'] : array();
			$studio_images = is_array( $bundle['studio_images'] ?? null ) ? $bundle['studio_images'] : array();
		}

		// ------------------------------------------------------------------
		// 1. Site Content Overrides (dot-paths or nested tree)
		// ------------------------------------------------------------------
		if ( ! empty( $content_updates ) ) {
			if ( isset( $content_updates['__nested__'] ) ) {
				$nested = self::sanitize_value( $content_updates['__nested__'] );
				if ( $enforce_caps && ! current_user_can( STBM_Roles::CAP_BRAND ) && ! current_user_can( 'manage_options' ) ) {
					unset( $nested['theme'] );
					if ( isset( $nested['global']['logo'] ) ) {
						unset( $nested['global']['logo'] );
					}
					$report['failed'][] = 'Skipped theme/logo keys: current WP user lacks Brand capability.';
				}
				if ( ! $dry_run ) {
					$base = 'replace' === $mode ? STBM_Defaults::get_default_site_content() : STBM_Defaults::get_site_content();
					update_option( STBM_Defaults::OPTION_SITE_CONTENT, STBM_Defaults::deep_merge_content( $base, $nested ) );
				}
				$report['counts']['contentKeys'] = count( $nested );
				$report['successful'][]          = 'Site content tree processed (' . count( $nested ) . ' top-level sections).';
			} else {
				$clean_paths = array();
				foreach ( $content_updates as $dot_key => $val ) {
					$k_str = sanitize_text_field( (string) $dot_key );
					if ( $enforce_caps && ( 0 === strpos( $k_str, 'theme.' ) || 0 === strpos( $k_str, 'global.logo.' ) ) ) {
						if ( ! current_user_can( STBM_Roles::CAP_BRAND ) && ! current_user_can( 'manage_options' ) ) {
							$report['failed'][] = "Blocked restricted brand key '{$k_str}' (requires Administrator / Business Manager role).";
							continue;
						}
					}
					if ( is_string( $val ) && ( false !== strpos( $k_str, 'image' ) || false !== strpos( $k_str, 'logo' ) ) && self::is_missing_image_ref( $val ) ) {
						$report['missing_images'][] = "Content key '{$k_str}' references unresolved image: {$val}";
					}
					$clean_paths[ $k_str ] = self::sanitize_value( $val );
				}
				if ( ! empty( $clean_paths ) ) {
					if ( ! $dry_run ) {
						if ( 'replace' === $mode ) {
							update_option( STBM_Defaults::OPTION_SITE_CONTENT, STBM_Defaults::get_default_site_content() );
						}
						STBM_Defaults::save_content_paths( $clean_paths );
					}
					$report['counts']['contentKeys'] = count( $clean_paths );
					$report['successful'][]          = count( $clean_paths ) . ' site content override path(s) applied.';
				}
			}
		}

		// ------------------------------------------------------------------
		// 2. Inventory Overrides (`cars`, `rentals`, `parts`, `gallery`, `faqs`, `careers`)
		// ------------------------------------------------------------------
		foreach ( array( 'cars', 'rentals', 'parts', 'gallery', 'faqs', 'careers' ) as $inv_type ) {
			if ( empty( $inventory_sections[ $inv_type ] ) || ! is_array( $inventory_sections[ $inv_type ] ) ) {
				continue;
			}
			$pt       = STBM_Defaults::map_inventory_cpt( $inv_type );
			$existing = STBM_Defaults::get_inventory_items( $inv_type );
			$by_slug  = array();
			$by_title = array();
			foreach ( $existing as $ex ) {
				if ( ! empty( $ex['slug'] ) ) {
					$by_slug[ $ex['slug'] ] = (int) $ex['id'];
				}
				$lbl = strtolower( trim( (string) ( $ex['name'] ?? $ex['title'] ?? $ex['q'] ?? '' ) ) );
				if ( '' !== $lbl ) {
					$by_title[ $lbl ] = (int) $ex['id'];
				}
			}

			if ( 'replace' === $mode && ! $dry_run && $pt ) {
				foreach ( get_posts( array( 'post_type' => $pt, 'post_status' => 'any', 'posts_per_page' => -1, 'fields' => 'ids' ) ) as $pid ) {
					wp_delete_post( $pid, true );
				}
				$by_slug  = array();
				$by_title = array();
			}

			$imported_cat = 0;
			foreach ( $inventory_sections[ $inv_type ] as $idx => $item ) {
				if ( ! is_array( $item ) ) {
					continue;
				}
				$img_ref = (string) ( $item['image'] ?? $item['url'] ?? '' );
				if ( self::is_missing_image_ref( $img_ref ) ) {
					$report['missing_images'][] = strtoupper( $inv_type ) . ' item missing image asset: ' . $img_ref;
				}

				$title_key = strtolower( trim( (string) ( $item['name'] ?? $item['title'] ?? $item['q'] ?? '' ) ) );
				$slug_key  = sanitize_title( $item['slug'] ?? $title_key );
				$match_id  = 0;
				if ( ! empty( $item['id'] ) && is_numeric( $item['id'] ) && get_post_type( (int) $item['id'] ) === $pt ) {
					$match_id = (int) $item['id'];
				} elseif ( $slug_key && isset( $by_slug[ $slug_key ] ) ) {
					$match_id = $by_slug[ $slug_key ];
				} elseif ( '' !== $title_key && isset( $by_title[ $title_key ] ) ) {
					$match_id = $by_title[ $title_key ];
				}

				if ( $match_id > 0 && 'merge' === $mode ) {
					$item['id'] = $match_id;
				} else {
					unset( $item['id'] );
				}
				if ( ! isset( $item['order'] ) ) {
					$item['order'] = $idx + 1;
				}

				if ( ! $dry_run ) {
					$res = STBM_Defaults::save_inventory_item( $inv_type, $item );
					if ( is_wp_error( $res ) ) {
						$report['failed'][] = strtoupper( $inv_type ) . ' error: ' . $res->get_error_message();
						continue;
					}
				}
				$imported_cat++;
				$report['counts']['inventory']++;
			}
			if ( $imported_cat > 0 ) {
				$report['successful'][] = strtoupper( $inv_type ) . ": {$imported_cat} record(s) synced.";
			}
		}

		// ------------------------------------------------------------------
		// 3. Billing Settings, Customers, Invoices, Receipts & Logs
		// ------------------------------------------------------------------
		if ( ! empty( $doc_settings ) ) {
			if ( ! empty( $doc_settings['logoDataUrl'] ) && self::is_missing_image_ref( $doc_settings['logoDataUrl'] ) ) {
				$report['missing_images'][] = 'Document Settings logo reference unresolved: ' . $doc_settings['logoDataUrl'];
			}
			if ( ! $dry_run ) {
				STBM_Defaults::save_doc_settings( $doc_settings );
			}
			$report['counts']['docSettings'] = 1;
			$report['successful'][]          = 'Document Settings (letterhead, currency, TIN, terms) imported.';
		}

		$t_cust = STBM_DB::table( 'customers' );
		$t_inv  = STBM_DB::table( 'invoices' );
		$t_rec  = STBM_DB::table( 'receipts' );
		$t_logs = STBM_DB::table( 'activity_logs' );

		if ( 'replace' === $mode && ! $dry_run && ( ! empty( $customers ) || ! empty( $invoices ) || ! empty( $receipts ) ) ) {
			$wpdb->query( "TRUNCATE TABLE {$t_rec}" );
			$wpdb->query( "TRUNCATE TABLE {$t_inv}" );
			$wpdb->query( "TRUNCATE TABLE {$t_cust}" );
		}

		// Track known Customer & Invoice UIDs for relational integrity verification.
		$known_customer_uids = array();
		if ( 'merge' === $mode ) {
			foreach ( STBM_DB::get_customers() as $c_row ) {
				$known_customer_uids[ $c_row['id'] ] = true;
			}
		}

		$cust_imported = 0;
		foreach ( $customers as $c ) {
			if ( ! is_array( $c ) ) {
				continue;
			}
			$c_uid  = sanitize_text_field( (string) ( $c['id'] ?? $c['uid'] ?? '' ) );
			$c_name = trim( (string) ( $c['name'] ?? '' ) );
			if ( '' === $c_name ) {
				$report['failed'][] = 'Skipped customer record missing required name (' . ( $c_uid ?: 'unknown' ) . ').';
				continue;
			}
			if ( 'merge' === $mode && '' !== $c_uid && isset( $known_customer_uids[ $c_uid ] ) ) {
				$report['skipped_duplicates'][] = "Customer {$c_uid} ({$c_name}) already exists (merged/updated).";
			}
			if ( $c_uid ) {
				$known_customer_uids[ $c_uid ] = true;
			}
			if ( ! $dry_run ) {
				$saved_c = STBM_DB::save_customer( $c, false );
				if ( is_wp_error( $saved_c ) ) {
					$report['failed'][] = "Customer {$c_name}: " . $saved_c->get_error_message();
					continue;
				}
				$known_customer_uids[ $saved_c['id'] ] = true;
			}
			$cust_imported++;
		}
		$report['counts']['customers'] = $cust_imported;
		if ( $cust_imported > 0 ) {
			$report['successful'][] = "Customers: {$cust_imported} record(s) processed.";
		}

		$known_invoice_uids = array();
		$existing_doc_nums  = array();
		if ( 'merge' === $mode ) {
			foreach ( STBM_DB::get_invoices() as $i_row ) {
				$known_invoice_uids[ $i_row['id'] ]       = true;
				$existing_doc_nums[ $i_row['docNumber'] ] = $i_row['id'];
			}
		}

		$inv_imported = 0;
		foreach ( $invoices as $inv ) {
			if ( ! is_array( $inv ) ) {
				continue;
			}
			$i_uid   = sanitize_text_field( (string) ( $inv['id'] ?? $inv['uid'] ?? '' ) );
			$doc_num = sanitize_text_field( (string) ( $inv['docNumber'] ?? '' ) );
			$cid     = sanitize_text_field( (string) ( $inv['customerId'] ?? '' ) );

			if ( '' !== $cid && ! isset( $known_customer_uids[ $cid ] ) ) {
				$report['broken_relationships'][] = "Invoice {$doc_num} references missing customerId '{$cid}' (snapshot customer name preserved).";
			}
			if ( 'merge' === $mode && ( ( $i_uid && isset( $known_invoice_uids[ $i_uid ] ) ) || ( $doc_num && isset( $existing_doc_nums[ $doc_num ] ) ) ) ) {
				if ( '' === $i_uid && isset( $existing_doc_nums[ $doc_num ] ) ) {
					$inv['id'] = $existing_doc_nums[ $doc_num ];
				}
				$report['skipped_duplicates'][] = "Invoice {$doc_num} already exists (merged/recalculated).";
			}
			if ( ! $dry_run ) {
				$saved_i = STBM_DB::save_invoice( $inv, false );
				if ( is_wp_error( $saved_i ) ) {
					$report['failed'][] = "Invoice {$doc_num}: " . $saved_i->get_error_message();
					continue;
				}
				$known_invoice_uids[ $saved_i['id'] ] = true;
			} elseif ( $i_uid ) {
				$known_invoice_uids[ $i_uid ] = true;
			}
			$inv_imported++;
		}
		$report['counts']['invoices'] = $inv_imported;
		if ( $inv_imported > 0 ) {
			$report['successful'][] = "Pro Forma Invoices: {$inv_imported} record(s) processed & totaled.";
		}

		$existing_rec_uids = array();
		$existing_rec_nums = array();
		if ( 'merge' === $mode ) {
			foreach ( STBM_DB::get_receipts() as $r_row ) {
				$existing_rec_uids[ $r_row['id'] ]            = true;
				$existing_rec_nums[ $r_row['receiptNumber'] ] = $r_row['id'];
			}
		}

		$rec_imported = 0;
		foreach ( $receipts as $rec ) {
			if ( ! is_array( $rec ) ) {
				continue;
			}
			$r_uid   = sanitize_text_field( (string) ( $rec['id'] ?? $rec['uid'] ?? '' ) );
			$rec_num = sanitize_text_field( (string) ( $rec['receiptNumber'] ?? '' ) );
			$cid     = sanitize_text_field( (string) ( $rec['customerId'] ?? '' ) );
			$iid     = sanitize_text_field( (string) ( $rec['invoiceId'] ?? '' ) );

			if ( '' !== $cid && ! isset( $known_customer_uids[ $cid ] ) ) {
				$report['broken_relationships'][] = "Receipt {$rec_num} references missing customerId '{$cid}' (snapshot customer preserved).";
			}
			if ( '' !== $iid && ! isset( $known_invoice_uids[ $iid ] ) ) {
				$report['broken_relationships'][] = "Receipt {$rec_num} references missing invoiceId '{$iid}'.";
			}
			if ( 'merge' === $mode && ( ( $r_uid && isset( $existing_rec_uids[ $r_uid ] ) ) || ( $rec_num && isset( $existing_rec_nums[ $rec_num ] ) ) ) ) {
				if ( '' === $r_uid && isset( $existing_rec_nums[ $rec_num ] ) ) {
					$rec['id'] = $existing_rec_nums[ $rec_num ];
				}
				$report['skipped_duplicates'][] = "Receipt {$rec_num} already exists (merged & balance synced).";
			}
			if ( ! $dry_run ) {
				$saved_r = STBM_DB::save_receipt( $rec, false );
				if ( is_wp_error( $saved_r ) ) {
					$report['failed'][] = "Receipt {$rec_num}: " . $saved_r->get_error_message();
					continue;
				}
			}
			$rec_imported++;
		}
		$report['counts']['receipts'] = $rec_imported;
		if ( $rec_imported > 0 ) {
			$report['successful'][] = "Official Receipts: {$rec_imported} record(s) processed & invoice balances synced.";
		}

		// Import legacy audit logs (deduplicated by uid).
		$log_imported = 0;
		foreach ( $activity_logs as $lg ) {
			if ( ! is_array( $lg ) ) {
				continue;
			}
			$l_uid = sanitize_text_field( (string) ( $lg['id'] ?? '' ) );
			if ( $l_uid ) {
				$exists_log = (int) $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$t_logs} WHERE uid = %s", $l_uid ) );
				if ( $exists_log > 0 ) {
					continue;
				}
			}
			if ( ! $dry_run ) {
				$ts = ! empty( $lg['timestamp'] ) ? gmdate( 'Y-m-d H:i:s', strtotime( $lg['timestamp'] ) ?: time() ) : current_time( 'mysql' );
				$wpdb->insert(
					$t_logs,
					array(
						'uid'             => $l_uid ?: ( 'log-' . wp_generate_uuid4() ),
						'log_timestamp'   => $ts,
						'action'          => sanitize_text_field( (string) ( $lg['action'] ?? 'import' ) ),
						'document_type'   => sanitize_text_field( (string) ( $lg['entityType'] ?? 'settings' ) ),
						'document_number' => sanitize_text_field( (string) ( $lg['entityTitle'] ?? '' ) ),
						'user_id'         => get_current_user_id(),
						'user_name'       => sanitize_text_field( (string) ( $lg['user'] ?? 'Legacy Admin' ) ),
						'details'         => sanitize_textarea_field( (string) ( $lg['details'] ?? '' ) ),
					)
				);
			}
			$log_imported++;
		}
		$report['counts']['activityLogs'] = $log_imported;

		// ------------------------------------------------------------------
		// 4. Image Studio Assets (IndexedDB / Fallback Base64 or Local Files)
		// ------------------------------------------------------------------
		$existing_studio_uids = array();
		if ( 'merge' === $mode ) {
			foreach ( STBM_DB::get_studio_images() as $s_row ) {
				$existing_studio_uids[ $s_row['id'] ] = true;
			}
		} elseif ( 'replace' === $mode && ! $dry_run && ! empty( $studio_images ) ) {
			$wpdb->query( 'TRUNCATE TABLE ' . STBM_DB::table( 'studio_images' ) );
		}

		$studio_imported = 0;
		foreach ( $studio_images as $st_img ) {
			if ( ! is_array( $st_img ) ) {
				continue;
			}
			$s_uid  = sanitize_text_field( (string) ( $st_img['id'] ?? '' ) );
			$s_name = sanitize_text_field( (string) ( $st_img['name'] ?? 'Studio Asset' ) );
			$raw_u  = (string) ( $st_img['dataUrl'] ?? $st_img['imageUrl'] ?? '' );

			if ( 0 === strpos( $raw_u, 'blob:' ) || ! empty( $st_img['_blobWarning'] ) ) {
				$report['missing_images'][] = "Studio asset '{$s_name}' had an expired browser blob URL that could not be serialized.";
				continue;
			}
			if ( self::is_missing_image_ref( $raw_u ) ) {
				$report['missing_images'][] = "Studio asset '{$s_name}' references missing image: {$raw_u}";
			}
			if ( 'merge' === $mode && $s_uid && isset( $existing_studio_uids[ $s_uid ] ) ) {
				$report['skipped_duplicates'][] = "Studio image '{$s_name}' ({$s_uid}) already exists (merged).";
			}

			if ( ! $dry_run ) {
				$saved_img = STBM_DB::save_studio_image(
					array(
						'id'           => $s_uid,
						'name'         => $s_name,
						'dataUrl'      => $raw_u,
						'width'        => (int) ( $st_img['width'] ?? 0 ),
						'height'       => (int) ( $st_img['height'] ?? 0 ),
						'format'       => (string) ( $st_img['format'] ?? 'image/jpeg' ),
						'size'         => (int) ( $st_img['size'] ?? 0 ),
						'category'     => (string) ( $st_img['category'] ?? 'General' ),
						'isEdited'     => ! empty( $st_img['isEdited'] ),
						'originalId'   => (string) ( $st_img['originalId'] ?? '' ),
						'originalName' => (string) ( $st_img['originalName'] ?? '' ),
					)
				);
				if ( is_wp_error( $saved_img ) ) {
					$report['failed'][] = "Studio image '{$s_name}': " . $saved_img->get_error_message();
					continue;
				}
			}
			$studio_imported++;
		}
		$report['counts']['studioImages'] = $studio_imported;
		if ( $studio_imported > 0 ) {
			$report['successful'][] = "Image Studio: {$studio_imported} asset(s) synced cleanly.";
		}

		if ( ! $dry_run ) {
			STBM_DB::log_activity( 'import', 'settings', 'Legacy Migration', sprintf( 'Imported %s (%s mode): %d content, %d inv, %d cust, %d inv-docs, %d rec, %d studio', $schema, $mode, $report['counts']['contentKeys'], $report['counts']['inventory'], $cust_imported, $inv_imported, $rec_imported, $studio_imported ) );
		}

		$report['ok'] = empty( $report['failed'] );
		return $report;
	}
}
